#!/usr/bin/env bash
# =============================================================================
# HERCOSSNUX PQC IP Core - Layer 3A step 1: FSM model and domain rules
#
# Before any ML-KEM RTL is written, this establishes the operation sequence the
# hardware will execute, using only the primitives the hardware has: the
# sponge, Montgomery-domain NTT-K/INTT-K, basemul with accumulate, the
# samplers and the codecs. Written against those primitives rather than the
# clean oracle, so domain and ordering mistakes surface in Python instead of
# in VHDL.
#
#   verif/fsm_model.py     the model, self-checking against ACVP
#   verif/gen_l3a.py       vector generator with intermediate checkpoints
#   verif/l3a_vectors.txt  4 KeyGen, 4 Encaps, 8 Decaps (4 implicit rejection)
#   doc/DOMAIN_RULES.md    normative Montgomery domain rules for the RTL
#
# Requires the Phase 0 delivery (verif/vectors/acvp_subset.json).
#
# Installs into: $HOME/vhdl_repo/IP_Cores/PQC/
# Expected single output line:
# FSM model matches ACVP through hardware primitives: 24 cases
# =============================================================================
set -u
(
  set -e
  DEST="$HOME/vhdl_repo/IP_Cores/PQC"
  mkdir -p "$DEST/verif" "$DEST/doc"
  if [ ! -f "$DEST/verif/vectors/acvp_subset.json" ]; then
    echo "MISSING PREREQUISITE: verif/vectors/acvp_subset.json (run the Phase 0 delivery first)"
    exit 1
  fi
  base64 -d > "$DEST/verif/fsm_model.py" << 'B64EOF'
